select
a.diagnose_plan_id,
a.signal_opt,
a.blur_opt,
a.contrast_opt,
a.bright_opt,
a.dark_opt,
a.chroma_opt,
a.mono_opt,
a.noise_opt,
a.streak_opt,
a.freeze_opt,
a.shake_opt,
a.flash_opt,
a.scene_opt,
a.cover_opt,
a.ptz_opt
from t_diagnose_plan_detail a
where 1 = 1
 and a.diagnose_plan_id = #{diagnosePlanId, jdbcType=VARCHAR}
 and a.signal_opt = #{signalOpt, jdbcType=VARCHAR}
 and a.blur_opt = #{blurOpt, jdbcType=VARCHAR}
 and a.contrast_opt = #{contrastOpt, jdbcType=VARCHAR}
 and a.bright_opt = #{brightOpt, jdbcType=VARCHAR}
 and a.dark_opt = #{darkOpt, jdbcType=VARCHAR}
 and a.chroma_opt = #{chromaOpt, jdbcType=VARCHAR}
 and a.mono_opt = #{monoOpt, jdbcType=VARCHAR}
